#include <iostream>
#include <cstdio>
#include <cstring>
using namespace std;

long long int gcd(long long int a, long long int b){
    while (b != 0) {
        long long int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

long long int lcm(long long int a, long long int b){
    return a * b / gcd(a, b);
}

int main(){
    long long int a[3], m[3], p[3] = {1, 1, 1}, c[3] = {0};

    while (true) {
        memset(c, 0, sizeof(c));
        // Using a single line of input to read all values at once
        if (!(cin >> a[0] >> m[0] >> a[1] >> m[1] >> a[2] >> m[2]) || a[0] == 0) break;

        for (int i = 0; i < 3; i++) {
            do {
                p[i] = (a[i] * p[i]) % m[i];
                c[i] += 1;
            } while (p[i] != 1);
        }

        cout << lcm(lcm(c[0], c[1]), c[2]) << endl;
    }
    return 0;
}

